// ***************
// Filename: ddr_ctrl_top.sv
// Author: FPGA Cores 4 U
// Description: ddr_ctrl with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map ddr_ctrl_regs
//   (u_regs, src/include/ddr_ctrl_regs.sv, ID "DDRC", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic ddr_ctrl (u_core,
//   src/ddr_ctrl.sv), joined by the register interface ddr_ctrl_regs_if
//   (u_regs_if). Generated by ip/scripts/regmap_gen.py from
//   ddr_ctrl_regs.json and the ports of ddr_ctrl: regenerate after changing
//   either. Clock - clk. Reset - synchronous active low rst_n.
// Date: 2026-10-21
module ddr_ctrl_top #(
  parameter int NPORTS = 2,
  parameter int DATA_W = 256,
  parameter int ADDR_W = 32,
  parameter int ID_W = 4,
  parameter int BANK_W = 3,
  parameter int ROW_W = 14,
  parameter int COL_W = 8,
  parameter int T_RCD = 4,
  parameter int T_RP = 4,
  parameter int T_RAS = 10,
  parameter int T_CL = 5,
  parameter int T_WR = 4,
  parameter int T_RTP = 2,
  parameter int T_WTR = 2,
  parameter int T_RRD = 2,
  parameter int T_RFC = 30,
  parameter int T_REFI = 1950,
  parameter int PRIORITY = 0,
  parameter int RQ_DEPTH = 16,
  parameter int BQ_DEPTH = 2
) (
  input  logic clk,
  input  logic rst_n,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  input  logic [NPORTS*ID_W-1:0] s_axi_awid,
  input  logic [NPORTS*ADDR_W-1:0] s_axi_awaddr,
  input  logic [NPORTS*8-1:0] s_axi_awlen,
  input  logic [NPORTS*3-1:0] s_axi_awsize,
  input  logic [NPORTS*2-1:0] s_axi_awburst,
  input  logic [NPORTS-1:0] s_axi_awvalid,
  output logic [NPORTS-1:0] s_axi_awready,
  input  logic [NPORTS*DATA_W-1:0] s_axi_wdata,
  input  logic [NPORTS*DATA_W/8-1:0] s_axi_wstrb,
  input  logic [NPORTS-1:0] s_axi_wlast,
  input  logic [NPORTS-1:0] s_axi_wvalid,
  output logic [NPORTS-1:0] s_axi_wready,
  output logic [NPORTS*ID_W-1:0] s_axi_bid,
  output logic [NPORTS*2-1:0] s_axi_bresp,
  output logic [NPORTS-1:0] s_axi_bvalid,
  input  logic [NPORTS-1:0] s_axi_bready,
  input  logic [NPORTS*ID_W-1:0] s_axi_arid,
  input  logic [NPORTS*ADDR_W-1:0] s_axi_araddr,
  input  logic [NPORTS*8-1:0] s_axi_arlen,
  input  logic [NPORTS*3-1:0] s_axi_arsize,
  input  logic [NPORTS*2-1:0] s_axi_arburst,
  input  logic [NPORTS-1:0] s_axi_arvalid,
  output logic [NPORTS-1:0] s_axi_arready,
  output logic [NPORTS*ID_W-1:0] s_axi_rid,
  output logic [NPORTS*DATA_W-1:0] s_axi_rdata,
  output logic [NPORTS*2-1:0] s_axi_rresp,
  output logic [NPORTS-1:0] s_axi_rlast,
  output logic [NPORTS-1:0] s_axi_rvalid,
  input  logic [NPORTS-1:0] s_axi_rready,
  output logic [2:0] dfi_cmd_o,
  output logic [BANK_W-1:0] dfi_bank_o,
  output logic [ROW_W-1:0] dfi_row_o,
  output logic [COL_W-1:0] dfi_col_o,
  output logic [DATA_W-1:0] dfi_wrdata_o,
  output logic [DATA_W/8-1:0] dfi_wrstrb_o,
  input  logic dfi_rddata_valid_i,
  input  logic [DATA_W-1:0] dfi_rddata_i
);
  // register interface between the register map and the logic
  ddr_ctrl_regs_if u_regs_if ();

  ddr_ctrl_regs u_regs (
    .clk,
    .rst_n,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  ddr_ctrl #(
    .NPORTS(NPORTS),
    .DATA_W(DATA_W),
    .ADDR_W(ADDR_W),
    .ID_W(ID_W),
    .BANK_W(BANK_W),
    .ROW_W(ROW_W),
    .COL_W(COL_W),
    .T_RCD(T_RCD),
    .T_RP(T_RP),
    .T_RAS(T_RAS),
    .T_CL(T_CL),
    .T_WR(T_WR),
    .T_RTP(T_RTP),
    .T_WTR(T_WTR),
    .T_RRD(T_RRD),
    .T_RFC(T_RFC),
    .T_REFI(T_REFI),
    .PRIORITY(PRIORITY),
    .RQ_DEPTH(RQ_DEPTH),
    .BQ_DEPTH(BQ_DEPTH)
  ) u_core (
    .clk,
    .rst_n,
    .s_axi_awid,
    .s_axi_awaddr,
    .s_axi_awlen,
    .s_axi_awsize,
    .s_axi_awburst,
    .s_axi_awvalid,
    .s_axi_awready,
    .s_axi_wdata,
    .s_axi_wstrb,
    .s_axi_wlast,
    .s_axi_wvalid,
    .s_axi_wready,
    .s_axi_bid,
    .s_axi_bresp,
    .s_axi_bvalid,
    .s_axi_bready,
    .s_axi_arid,
    .s_axi_araddr,
    .s_axi_arlen,
    .s_axi_arsize,
    .s_axi_arburst,
    .s_axi_arvalid,
    .s_axi_arready,
    .s_axi_rid,
    .s_axi_rdata,
    .s_axi_rresp,
    .s_axi_rlast,
    .s_axi_rvalid,
    .s_axi_rready,
    .dfi_cmd_o,
    .dfi_bank_o,
    .dfi_row_o,
    .dfi_col_o,
    .dfi_wrdata_o,
    .dfi_wrstrb_o,
    .dfi_rddata_valid_i,
    .dfi_rddata_i,
    .regs(u_regs_if)
  );
endmodule
